                          Conversão: R$ {depositAmount || '0'} = <span className="text-pandora-primary font-bold">{(Number(depositAmount)/10).toFixed(1)} PND</span>
                       </p>
                    </div>
                    <button onClick={handleGeneratePix} className="w-full bg-green-600 hover:bg-green-500 text-white font-bold py-4 rounded-xl uppercase tracking-wider transition-colors shadow-lg shadow-green-900/20">
                       Gerar Pix
                    </button>
                 </div>
              )}

              {topUpStep === 'payment' && (
                 <div className="text-center">
                    <div className="bg-white p-4 rounded-xl inline-block mb-4">
                       <QrCode className="w-40 h-40 text-black" />
                    </div>
                    <p className="text-xs text-gray-400 mb-4">Escaneie o QR Code ou use o código abaixo</p>
                    <div className="bg-black/40 border border-white/10 p-3 rounded-lg flex items-center gap-2 mb-6">
                       <code className="flex-1 text-xs text-gray-300 font-mono truncate">{generatedPixCode}</code>
                       <button onClick={() => { navigator.clipboard.writeText(generatedPixCode); alert('Código copiado!'); }} className="text-pandora-primary font-bold hover:text-white">Copiar</button>
                    </div>
                    <button onClick={handleConfirmPixPayment} className="w-full bg-green-600 hover:bg-green-500 text-white font-bold py-4 rounded-xl uppercase tracking-wider transition-colors shadow-lg">
                       Já fiz o pagamento
                    </button>
                 </div>
              )}

              {topUpStep === 'processing' && (
                 <div className="py-12 text-center">
                    <Loader2 className="w-12 h-12 text-green-500 animate-spin mx-auto mb-4" />
                    <h3 className="text-white font-bold text-lg">Processando...</h3>
                    <p className="text-sm text-gray-500">Verificando seu pagamento.</p>
                 </div>
              )}
           </div>
        </div>
       )}

    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { User, QrCode, Copy, Loader2, Lock, ArrowRight, ShieldCheck, CheckCircle2, PartyPopper, Ticket, Scale, Fingerprint, AlertCircle, MapPin } from 'lucide-react';
import { User as UserType } from '../types';
import { validateRegistrationName } from '../services/geminiService';

interface SignupFormProps {
  onSignup: (user: UserType) => void;
  onCancel: () => void;
  adminPixKey: string;
}

const SignupForm: React.FC<SignupFormProps> = ({ onSignup, onCancel, adminPixKey }) => {
  const [step, setStep] = useState<1 | 2>(1);
  const [role, setRole] = useState<'requester' | 'worker' | 'both'>('requester');

  // Dados Gerais
  const [formData, setFormData] = useState({
    name: '',
    cpf: '',
    phone: '',
    pixKey: ''
  });

  // Dados Específicos de Endereço
  const [addressData, setAddressData] = useState({
    cep: '',
    street: '',
    number: '',
    neighborhood: '',
    city: ''
  });

  // Verification States
  const [isVerifyingIdentity, setIsVerifyingIdentity] = useState(false);
  const [verificationStatus, setVerificationStatus] = useState<'idle' | 'success' | 'error'>('idle');
  const [verificationMessage, setVerificationMessage] = useState('');

  const [isProcessing, setIsProcessing] = useState(false);

  // Pix Payload for Payment (Simulated)
  const [pixPayload, setPixPayload] = useState('');

  // --- PROMOÇÃO DE LANÇAMENTO ---
  const IS_FREE_CAMPAIGN = true;

  // Cents Identifier: Generate random cents once to identify the transaction
  const [randomCents] = useState(() => Math.floor(Math.random() * 90) + 10); // 10 to 99 cents

  // Fee calculation
  const baseFee = role === 'both' ? 7 : (role === 'requester' ? 5 : 2);
  const feeWithCents = baseFee + (randomCents / 100);
  const fee = IS_FREE_CAMPAIGN ? 0 : feeWithCents;

  useEffect(() => {
     if (step === 2 && fee > 0) {
        // Generate mock payload when entering payment step
        const mock = `00020126580014br.gov.bcb.pix0136${Math.random().toString(36).substring(7)}520400005303986540${fee.toFixed(2).replace('.', '')}5802BR5913C PANDOX LTDA6008BRASILIA62070503***6304${Math.floor(Math.random() * 9000) + 1000}`;
        setPixPayload(mock);
     }
  }, [step, fee]);

  // Algoritmo Oficial de Validação de CPF (Módulo 11)
  const isValidCPF = (cpf: string) => {
    cpf = cpf.replace(/[^\d]+/g, '');
    if (cpf.length !== 11 || /^(\d)\1+$/.test(cpf)) return false;

    let sum = 0;
    let remainder;

    for (let i = 1; i <= 9; i++) sum += parseInt(cpf.substring(i - 1, i)) * (11 - i);
    remainder = (sum * 10) % 11;
    if ((remainder === 10) || (remainder === 11)) remainder = 0;
    if (remainder !== parseInt(cpf.substring(9, 10))) return false;

    sum = 0;
    for (let i = 1; i <= 10; i++) sum += parseInt(cpf.substring(i - 1, i)) * (12 - i);
    remainder = (sum * 10) % 11;
    if ((remainder === 10) || (remainder === 11)) remainder = 0;
    if (remainder !== parseInt(cpf.substring(10, 11))) return false;

    return true;
  };

  const handleNext = async () => {
    // 1. Basic Fields Check
    if (!formData.name || !formData.cpf || !formData.phone || !formData.pixKey) {
      alert("Por favor, preencha todos os dados pessoais obrigatórios (Nome, CPF, Celular, Pix).");
      return;
    }

    // 2. Address Strict Check
    if (!addressData.cep || !addressData.street || !addressData.number || !addressData.neighborhood || !addressData.city) {
      alert("Por favor, preencha o endereço completo (CEP, Rua, Número, Bairro e Cidade) conforme exigido.");
      return;
    }

    setVerificationStatus('idle');
    setVerificationMessage('');
    setIsVerifyingIdentity(true);

    // 3. Validate CPF Format (Math)
    if (!isValidCPF(formData.cpf)) {
        setIsVerifyingIdentity(false);
        setVerificationStatus('error');
        setVerificationMessage('CPF Inválido. Verifique os dígitos e tente novamente.');
        return;
    }

    // 4. Validate Name (via AI) and Simulate Gov Database Check
    try {
        // Parallel execution: AI Name Check + Artificial Delay for "Database Query"
        const [nameCheck] = await Promise.all([
            validateRegistrationName(formData.name),
            new Promise(resolve => setTimeout(resolve, 2500)) // Simula tempo de resposta do Gov.br
        ]);

        if (!nameCheck.valid) {
            setIsVerifyingIdentity(false);
            setVerificationStatus('error');
            setVerificationMessage(`Nome Rejeitado: ${nameCheck.message || 'Informe seu nome civil completo sem abreviações.'}`);
            return;
        }

        // Simulação de Sucesso na "Consulta à Receita"
        setIsVerifyingIdentity(false);
        setVerificationStatus('success');

        // Pequeno delay visual para mostrar o sucesso antes de trocar de tela
        setTimeout(() => {
            setStep(2);
        }, 1000);

    } catch (e) {
        setIsVerifyingIdentity(false);
        // Fallback allow in case of AI error, but maintain CPF math check
        setStep(2);
    }
  };

  const handlePaymentConfirm = () => {
    setIsProcessing(true);
    setTimeout(() => {
      // Construct full address string
      const fullAddressString = `${addressData.street}, ${addressData.number} - ${addressData.neighborhood}, ${addressData.city} - CEP: ${addressData.cep}`;

