      const newUser: UserType = {
        id: `user_${Math.random().toString(36).substr(2, 9)}`,
        name: formData.name,
        avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${formData.name}`,
        rating: 5.0,
        walletBalance: 0,
        status: 'active',
        // Sensitive Data
        cpf: formData.cpf,
        address: fullAddressString, // Full string saved
        phone: formData.phone,
        pixKey: formData.pixKey,
        role: role,
        isVerified: true
      };

      onSignup(newUser);
      setIsProcessing(false);
    }, 2500);
  };

  const copyPixKey = (text: string) => {
    navigator.clipboard.writeText(text);
    alert("Código copiado!");
  };

  const formatCPF = (value: string) => {
    return value
      .replace(/\D/g, '')
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d{1,2})/, '$1-$2')
      .replace(/(-\d{2})\d+?$/, '$1');
  };

  const formatCEP = (value: string) => {
    return value
      .replace(/\D/g, '')
      .replace(/^(\d{5})(\d)/, '$1-$2')
      .slice(0, 9);
  };

  return (
    <div className="max-w-xl mx-auto py-8 px-4">
      <div className="bg-pandora-card border border-white/10 rounded-3xl p-8 shadow-2xl relative overflow-hidden">
        {/* Progress Bar */}
        <div className="absolute top-0 left-0 w-full h-1 bg-gray-800">
          <div 
            className="h-full bg-pandora-primary transition-all duration-500" 
            style={{ width: step === 1 ? '50%' : '100%' }}
          ></div>
        </div>

        <div className="mb-6 text-center">
          <h2 className="text-2xl font-black text-white uppercase tracking-tight mb-2">
            Inscrição C.Pandox
          </h2>
          <p className="text-sm text-gray-400">
            {step === 1 ? 'Validação de Identidade' : 'Confirmação de Cadastro'}
          </p>
        </div>

        {/* --- BANNER PROMOCIONAL --- */}
        {IS_FREE_CAMPAIGN && (
           <div className="bg-gradient-to-r from-green-600 to-emerald-600 p-4 rounded-xl mb-6 text-center shadow-lg shadow-green-900/20 animate-pulse relative overflow-hidden border border-white/10">
              <div className="absolute inset-0 bg-white/10 skew-x-12 translate-x-full animate-shimmer"></div>
              <p className="text-white font-black text-xs uppercase tracking-widest mb-1 flex items-center justify-center gap-2">
                 <PartyPopper className="w-4 h-4" /> Campanha de Lançamento
              </p>
              <p className="text-white font-bold text-sm md:text-base">
                 OS PRIMEIROS 100 CADASTROS SÃO <span className="underline decoration-wavy decoration-white/50">GRATUITOS</span>!
              </p>
           </div>
        )}

        {/* ... (Keep Identity Check Overlay and Step 1 Content as is) ... */}
        {isVerifyingIdentity && (
            <div className="absolute inset-0 z-50 bg-pandora-card/95 backdrop-blur-sm flex flex-col items-center justify-center p-8 text-center animate-in fade-in duration-300">
                <div className="relative mb-6">
                    <div className="absolute inset-0 bg-blue-500/30 blur-xl rounded-full animate-pulse"></div>
                    <Scale className="w-16 h-16 text-blue-400 relative z-10 animate-bounce" />
                </div>
                <h3 className="text-xl font-bold text-white mb-2">Consultando Base Federal...</h3>
                <p className="text-sm text-gray-400 mb-6">Estamos verificando a correspondência do CPF com o Nome Civil informado.</p>
                <div className="w-64 h-2 bg-gray-800 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 animate-[loading_2s_ease-in-out_infinite] w-full origin-left"></div>
                </div>
                <p className="text-xs text-gray-600 mt-4 font-mono uppercase">Conexão Segura: Gov.br</p>
            </div>
        )}

        {step === 1 && (
          <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
            {/* Role Selection */}
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase mb-3 text-center">Qual seu objetivo principal?</label>
