                  </p>
                </button>
                <button
                  onClick={() => setRole('worker')}
                  className={`p-3 rounded-xl border transition-all flex flex-col items-center justify-center ${role === 'worker' ? 'bg-pandora-secondary/20 border-pandora-secondary text-white shadow-[0_0_20px_rgba(249,115,22,0.2)]' : 'bg-black/20 border-white/10 text-gray-500 hover:bg-white/5'}`}
                >
                  <p className="font-bold text-xs">SÓ TRABALHAR</p>
                  <p className="text-[10px] mt-1">
