    }

    if (view === 'chat_detail' && activeSession) {
       const currentGig = requests.find(r => r.id === activeSession.gigId);
       const isChatUnlocked = currentGig && (currentGig.status === GigStatus.IN_PROGRESS || currentGig.status === GigStatus.COMPLETED);
       return (
