                )}
             </div>
          </div>
       );
    }

    if (view === 'create') {
       return (
         <div className="container mx-auto px-4 py-8">
            <CreateGigForm onSubmit={handleSaveGig} onCancel={() => setView('home')} initialDescription={draftDescription} initialType={createFormInitialType} currentUser={currentUser} onRedirectToSignup={() => setView('signup')} gigToEdit={gigToEdit} />
         </div>
       );
    }

    if (view === 'messages') {
       return (
         <div className="container mx-auto px-4 py-8">
            <div className="max-w-2xl mx-auto space-y-4">
              <h2 className="text-2xl font-bold mb-6 text-white">Mensagens</h2>
              {chats.length === 0 && (<div className="text-center py-10 text-gray-500"><MessageSquare className="w-12 h-12 mx-auto mb-2 opacity-20" /><p>Nenhuma conversa ativa.</p><p className="text-xs">Contrate um serviço para liberar o chat.</p></div>)}
              {chats.map(chat => (<div key={chat.id} onClick={() => handleOpenChat(chat)} className="bg-pandora-card p-4 rounded-2xl border border-white/5 hover:border-pandora-primary/30 cursor-pointer flex items-center gap-4 transition-all"><img src={chat.participant.avatar} alt="" className="w-12 h-12 rounded-full border border-white/10" /><div className="flex-1"><div className="flex justify-between mb-1"><h3 className="font-bold text-white">{chat.participant.name}</h3>{chat.unreadCount > 0 && <span className="bg-pandora-primary text-white text-xs px-2 py-0.5 rounded-full">{chat.unreadCount} nova(s)</span>}</div><p className="text-sm text-gray-400 truncate">{chat.lastMessage}</p></div></div>))}
            </div>
