                {isAdminSetup ? (
                   <div className="flex items-center justify-between"><p className="text-xs text-green-500 font-bold flex items-center gap-1"><Check className="w-3 h-3" /> Configuração Ativa</p><button onClick={() => setView('admin_login')} className="bg-white/5 hover:bg-white/10 text-gray-300 px-4 py-2 rounded-lg text-xs font-bold uppercase transition-colors">Acesso Painel</button></div>
                ) : (
                   <div className="flex items-center justify-between"><p className="text-xs text-gray-500">Configuração inicial pendente.</p><button onClick={() => setShowAdminSetupModal(true)} className="bg-pandora-primary/20 text-pandora-primary hover:bg-pandora-primary/30 px-4 py-2 rounded-lg text-xs font-bold uppercase transition-colors border border-pandora-primary/20">Configurar Acesso</button></div>
                )}
             </div>
          </div>
       );
    }

    if (view === 'create') {
       return (
         <div className="container mx-auto px-4 py-8">
            <CreateGigForm onSubmit={handleSaveGig} onCancel={() => setView('home')} initialDescription={draftDescription} initialType={createFormInitialType} currentUser={currentUser} onRedirectToSignup={() => setView('signup')} gigToEdit={gigToEdit} />
         </div>
       );
    }

    if (view === 'messages') {
       return (
         <div className="container mx-auto px-4 py-8">
