const RenderRevenueChart = () => {
  const points = [10, 25, 18, 40, 35, 60, 50, 85, 70, 95];
  const max = 100;
  const width = 100;
  const height = 50;

  const polylinePoints = points.map((p, i) => {
    const x = (i / (points.length - 1)) * width;
    const y = height - (p / max) * height;
    return `${x},${y}`;
  }).join(' ');

  return (
    <div className="w-full h-full min-h-[150px] relative">
      <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-full overflow-visible" preserveAspectRatio="none">
        <defs>
          <linearGradient id="chartGradient" x1="0" x2="0" y1="0" y2="1">
            <stop offset="0%" stopColor="#8B5CF6" stopOpacity="0.5" />
            <stop offset="100%" stopColor="#8B5CF6" stopOpacity="0" />
          </linearGradient>
        </defs>
        <path d={`M 0,${height} ${polylinePoints} L ${width},${height} Z`} fill="url(#chartGradient)" />
        <polyline 
          points={polylinePoints} 
          fill="none" 
          stroke="#8B5CF6" 
          strokeWidth="1.5" 
          vectorEffect="non-scaling-stroke"
          className="drop-shadow-[0_0_5px_rgba(139,92,246,0.5)]"
        />
        {points.map((p, i) => {
           const x = (i / (points.length - 1)) * width;
           const y = height - (p / max) * height;
           return (
             <circle key={i} cx={x} cy={y} r="1.5" fill="white" className="animate-pulse" />
           );
        })}
      </svg>
      <div className="absolute inset-0 border-t border-b border-white/5 flex flex-col justify-between pointer-events-none">
        <div className="border-b border-white/5 border-dashed h-1/4 w-full"></div>
        <div className="border-b border-white/5 border-dashed h-1/4 w-full"></div>
        <div className="border-b border-white/5 border-dashed h-1/4 w-full"></div>
      </div>
    </div>
  );
};

