  const handleSendMessage = async (sessionId: string, text: string, attachment?: { type: 'image' | 'video', url: string }) => {
    const newMessage: Message = {
      id: Math.random().toString(36).substr(2, 9),
      senderId: currentUser.id,
      content: text,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      isMe: true,
      attachment: attachment
    };

    // Save Service
    await api.chats.sendMessage(sessionId, newMessage);

    // Update Local
    setChats(prevChats => {
      const updatedChats = prevChats.map(chat => {
        if (chat.id === sessionId) {
          return {
            ...chat,
            lastMessage: attachment ? (attachment.type === 'image' ? '📷 Imagem' : '🎥 Vídeo') : text,
            messages: [...chat.messages, newMessage]
          };
        }
        return chat;
      });
      const updatedActive = updatedChats.find(c => c.id === sessionId);
      if (updatedActive) {
        setActiveSession(updatedActive);
      }
      return updatedChats;
    });
  };

  const handleGigClick = (request: GigRequest) => {
    setSelectedGigDetail(request);
  };

  const handleHireClick = (gigId: string) => {
    if (!currentUser.isVerified) {
        if (confirm("VOCÊ ESTÁ QUASE LÁ!\n\nPara negociar, aceitar propostas ou contratar, é necessário validar seu perfil no C.Pandox.\n\nDeseja finalizar seu cadastro agora para liberar o acesso?")) {
            setSelectedGigDetail(null); 
            setView('signup');
        }
        return;
    }
    const gig = requests.find(r => r.id === gigId);
    if (gig) {
      if (gig.author.id === currentUser.id) {
          // Owner cannot "hire" from card, they use View Candidates
          return;
      }

      // Check if chat already exists
      const existingChat = chats.find(c => c.gigId === gig.id && c.participant.id === gig.author.id);
      if (existingChat) {
          handleOpenChat(existingChat);
          return;
      }

      // Create new chat negotiation
      const newChatSession: ChatSession = {
          id: `chat_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
          gigId: gig.id,
          participant: gig.author,
          lastMessage: "Iniciou interesse no pedido.",
          unreadCount: 0,
          messages: []
      };

      handleOpenChat(newChatSession);
      // Logic inside handleOpenChat adds user to candidates
    }
  };

  // OWNER: Open Modal to Select Candidate
  const handleViewCandidates = (gig: GigRequest) => {
     setSelectedGigForCandidates(gig);
     setShowCandidatesModal(true);
  };

  // OWNER: Select a candidate to start chat specifically with them
  const handleSelectCandidate = async (candidate: UserType) => {
      if (!selectedGigForCandidates) return;

      // Check if chat already exists for this candidate on this gig
      const existingChat = chats.find(c => c.gigId === selectedGigForCandidates.id && c.participant.id === candidate.id);

      if (existingChat) {
          setShowCandidatesModal(false);
          setActiveSession(existingChat);
          setView('chat_detail');
          return;
      }

      // Create new chat
      const newChatId = `chat_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`;
      const newChatSession: ChatSession = {
          id: newChatId,
          gigId: selectedGigForCandidates.id,
          participant: candidate,
          lastMessage: "Olá! Vi seu interesse no meu pedido. Vamos conversar?",
          unreadCount: 0,
          messages: [
              {
                  id: 'init_owner',
                  senderId: currentUser.id,
                  content: "Olá! Vi seu interesse no meu pedido. Vamos conversar?",
                  timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                  isMe: true
              }
          ]
      };

      await api.chats.create(newChatSession);
      setChats(prev => [newChatSession, ...prev]);

      setShowCandidatesModal(false);
      setActiveSession(newChatSession);
      setView('chat_detail');
  };


  const confirmHire = async () => {
    if (!selectedGigForHire) return;
    if (!paymentPixKey) {
      alert("Por favor, insira sua chave Pix para validar a transação.");
      return;
    }
    if (userBalance >= selectedGigForHire.budget) {
      setIsProcessingPayment(true);
      setTimeout(async () => {
        setUserBalance(prev => prev - selectedGigForHire.budget);
        addLog(`Cofre ativado para pedido ${selectedGigForHire.id}. Valor: ${selectedGigForHire.budget}`, 'info');

        const updatedGig = { ...selectedGigForHire, status: GigStatus.IN_PROGRESS };
        await api.gigs.update(updatedGig);

        const updatedRequests = requests.map(req => 
          req.id === selectedGigForHire.id 
            ? updatedGig
            : req
        );
        setRequests(updatedRequests);

        const newChatId = `chat_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`;

        if (activeSession && activeSession.gigId === selectedGigForHire.id) {
            const systemMsg: Message = {
               id: 'sys_safe',
               senderId: 'system',
               content: `Cofre Pandox ativado! O valor de ${selectedGigForHire.budget} PND está seguro.`,
               timestamp: new Date().toLocaleTimeString(),
               isMe: false
            };
            await api.chats.sendMessage(activeSession.id, systemMsg);
        }

        setShowPaymentModal(false);
        setSelectedGigForHire(null);
        setPaymentPixKey('');
        setIsProcessingPayment(false);
        alert("Pagamento confirmado e valor retido no Cofre! O chat foi liberado.");
      }, 2500);
    } else {
      alert("Saldo insuficiente. Recarregue suas Pandox Coins.");
      setIsProcessingPayment(false);
    }
  };

  const handleReleaseFunds = async (gigId: string) => {
    const gig = requests.find(r => r.id === gigId);
    if (!gig) return;
    const commissionFee = Math.floor(gig.budget * (commissionRate / 100));
    const providerAmount = gig.budget - commissionFee;
    setAppRevenue(prev => prev + commissionFee);
    addLog(`Pagamento liberado (ID: ${gigId}). Comissão App: ${commissionFee} PND`, 'success');

    const updatedGig = { ...gig, status: GigStatus.COMPLETED };
    await api.gigs.update(updatedGig);

    const updatedRequests = requests.map(req => 
      req.id === gigId 
        ? updatedGig 
        : req
    );
    setRequests(updatedRequests);
    alert(`
      Serviço confirmado e concluído!
      --------------------------------
      Valor Total: ${gig.budget} PND
      Taxa da Plataforma (${commissionRate}%): -${commissionFee} PND (Depositado em c.pandox)
      Valor Líquido Liberado ao Prestador: ${providerAmount} PND
    `);
  };

  const handleGeneratePix = () => {
    if (!depositAmount || Number(depositAmount) <= 0) return;

    // Add random cents for identification
    const cents = Math.floor(Math.random() * 99) + 1;
    const exactAmount = Number(depositAmount) + (cents / 100);
    setIdentifiedDepositAmount(exactAmount);

    const mockPayload = `00020126580014br.gov.bcb.pix0136${Math.random().toString(36).substring(7)}520400005303986540${exactAmount.toFixed(2).replace('.', '')}5802BR5913C PANDOX LTDA6008BRASILIA62070503***6304${Math.floor(Math.random() * 9000) + 1000}`;
    setGeneratedPixCode(mockPayload);
    setTopUpStep('payment');
  };

  const handleConfirmPixPayment = () => {
    setTopUpStep('processing');
    setTimeout(async () => {
      // Credit the identified amount
      const amountToAdd = identifiedDepositAmount / 10; 
      const newTrans: Transaction = {
         id: Math.random().toString(36).substr(2, 9),
         userId: currentUser.id,
         userName: currentUser.name,
         amount: identifiedDepositAmount,
         coins: amountToAdd,
         type: 'deposit',
         status: 'pending',
         pixCode: generatedPixCode,
         timestamp: new Date().toLocaleString()
      };

      await api.system.addTransaction(newTrans);

      setTransactions([newTrans, ...transactions]);
      addLog(`Novo depósito pendente de R$ ${identifiedDepositAmount.toFixed(2)} por ${currentUser.name}`, 'info');
      setTopUpStep('amount');
      setDepositAmount('');
      setIdentifiedDepositAmount(0);
      setShowTopUpModal(false);
      alert(`Depósito registrado! Seu saldo será atualizado assim que o pagamento for identificado pelo sistema bancário.`);
    }, 2000);
  };

  const handleAdminApproveTransaction = (transId: string) => {
     const trans = transactions.find(t => t.id === transId);
     if (!trans) return;
     setAllUsers(users => users.map(u => {
        if (u.id === trans.userId) {
           return { ...u, walletBalance: u.walletBalance + trans.coins };
        }
        return u;
     }));
     if (trans.userId === currentUser.id) {
        setUserBalance(prev => prev + trans.coins);
     }
     setTransactions(transactions.map(t => t.id === transId ? { ...t, status: 'approved' } : t));
     setAppRevenue(prev => prev + trans.coins);
     addLog(`Depósito de R$ ${trans.amount} aprovado para ${trans.userName}`, 'success');
  };

  const handleAdminRejectTransaction = (transId: string) => {
     if(confirm('Rejeitar este pagamento?')) {
        setTransactions(transactions.map(t => t.id === transId ? { ...t, status: 'rejected' } : t));
        addLog(`Depósito rejeitado (ID: ${transId})`, 'warning');
     }
  };

  const handleSetupAdmin = () => {
    if (!adminConfig.name || !adminConfig.password) {
      alert("Por favor, preencha todos os campos.");
      return;
    }
    setIsAdminSetup(true);
    addLog('Administrador configurado com sucesso.', 'warning');
    setShowAdminSetupModal(false);
    alert("Acesso administrativo configurado!");
  };

  const handleAdminLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setAdminLoginError('');
    if (!isAdminSetup) {
       setAdminLoginError('Administrador ainda não configurado. Configure na Carteira primeiro.');
       return;
    }
    const name = adminLoginName.trim();
    const pass = adminLoginPass.trim();
    if (name === adminConfig.name && pass === adminConfig.password) {
      setAdminUser(adminConfig.name);
      addLog(`Admin ${adminConfig.name} acessou o SATI.`, 'warning');
      setView('admin_dashboard');
    } else {
      setAdminLoginError('Credenciais inválidas.');
      addLog(`Tentativa de acesso falha ao SATI: ${name}`, 'error');
    }
  };

  const handleSaveCorporatePix = () => {
    if(!newPixKey.trim()) return;
    setCorporatePixKey(newPixKey);
    setIsEditingPix(false);
    addLog(`Chave Pix Corporativa alterada para: ${newPixKey}`, 'warning');
  };

  const handleUserDeleteGig = async (gigId: string) => {
    if (confirm('Deseja realmente remover este item?')) {
      await api.gigs.delete(gigId);
      setRequests(requests.filter(r => r.id !== gigId));
      addLog(`Usuário removeu seu próprio pedido ${gigId}`, 'info');
    }
  };

  const handleResetApp = () => {
    if (confirm('ATENÇÃO: Isso apagará todas as suas conversas, pedidos e inspirações salvas localmente para reiniciar os testes. Deseja continuar?')) {
      localStorage.clear();
      window.location.reload();
    }
  };

  // ATUALIZADO PARA WHATSAPP DIRETO
  const handleShareApp = () => {
    const url = window.location.href;
    const text = "c.pandox - O marketplace de desejos inusitados. Confira: ";
    const whatsappUrl = `https://api.whatsapp.com/send?text=${encodeURIComponent(text + url)}`;
    window.open(whatsappUrl, '_blank');
  };

  const runTransferSequence = () => {
    let currentStep = 0;
    setTransferConsoleLogs([]);
    const interval = setInterval(() => {
      if (currentStep >= 7) {
        clearInterval(interval);
        addLog(`Saque Corporativo Realizado. Valor: R$ ${(appRevenue * 10).toFixed(2)}`, 'warning');
        setAppRevenue(0);
        setShowAdminWithdrawModal(false);
        setAdminWithdrawPass('');
        setAdminStep('auth');
        alert('Autenticação Confirmada. Valor transferido com sucesso.');
      } else {
        const steps = [
            "Iniciando...", "Conectando...", "Validando...", "Autenticando...", "Debitando...", "Confirmando...", "SUCESSO"
        ];
        setTransferConsoleLogs(prev => [...prev, steps[currentStep] || "..."]);
        currentStep++;
      }
    }, 800);
  };

  const handleAdminAuthSubmit = () => {
    setAdminError('');
    if (adminStep === 'auth') {
      if (adminWithdrawPass === adminConfig.password) { 
        setAdminStep('processing');
        runTransferSequence();
      } else {
        setAdminError(`Senha incorreta.`);
      }
    }
  };

  const filteredRequests = requests.filter(req => {
    const matchesTerm = req.title.toLowerCase().includes(filterTerm.toLowerCase()) || 
                        req.description.toLowerCase().includes(filterTerm.toLowerCase());
    const matchesCategory = selectedCategory === 'Todos' || req.category === selectedCategory;
    const matchesType = req.type === listingTypeFilter;
    return matchesTerm && matchesCategory && matchesType;
  });

  if (maintenanceMode && view !== 'admin_login' && view !== 'admin_dashboard') {
    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center text-center p-8">
        <Siren className="w-24 h-24 text-red-500 animate-pulse mb-8" />
        <h1 className="text-4xl font-black text-white mb-4 tracking-wider">SISTEMA EM MANUTENÇÃO</h1>
        <p className="text-gray-500 max-w-md mx-auto">
          O C.Pandox está passando por atualizações críticas de segurança. Por favor, retorne em breve.
        </p>
        <button onClick={() => setView('admin_login')} className="mt-12 text-gray-700 hover:text-white text-xs uppercase tracking-widest">
          Acesso Técnico
        </button>
      </div>
    );
  }

  // --- VIEW RENDERING HELPERS ---
  const renderMainContent = () => {
    if (view === 'signup') return <SignupForm onSignup={handleSignup} onCancel={() => setView('home')} adminPixKey={corporatePixKey} />;

    if (view === 'wallet') {
       return (
          <div className="container mx-auto px-4 py-8 max-w-2xl">
             <div className="bg-pandora-card rounded-3xl border border-white/10 p-8 mb-8 relative overflow-hidden">
                <div className="absolute top-0 right-0 w-64 h-64 bg-gradient-to-bl from-amber-500/10 to-transparent rounded-full pointer-events-none blur-3xl"></div>
                <p className="text-gray-400 font-bold uppercase text-xs tracking-wider mb-2">Saldo Disponível</p>
                <h2 className="text-5xl font-mono font-bold text-white mb-6 flex items-center gap-2">
                   <Gem className="w-8 h-8 text-amber-500" /> {userBalance.toFixed(0)} <span className="text-xl text-gray-500">PND</span>
                </h2>
                <div className="mt-6">
                   <button onClick={() => setShowTopUpModal(true)} className="w-full bg-green-600 hover:bg-green-500 text-white py-4 rounded-xl font-bold flex items-center justify-center gap-3 transition-all shadow-lg shadow-green-900/20 group">
                      <ArrowDownLeft className="w-5 h-5" />
                      <span className="uppercase tracking-wider text-sm">Adicionar Créditos</span>
                   </button>
                   <p className="text-xs text-gray-500 mt-3 text-center">* Depósitos são convertidos em créditos (PND). Saques não permitidos para depósitos.</p>
                </div>
             </div>

             {transactions.filter(t => t.userId === currentUser.id && t.status === 'pending').length > 0 && (
                <div className="bg-yellow-900/10 border border-yellow-500/20 p-4 rounded-xl mb-8">
                   <h4 className="text-yellow-500 text-sm font-bold mb-2 flex items-center gap-2"><Clock className="w-4 h-4" /> Pagamentos em Análise</h4>
                   <div className="space-y-2">
                      {transactions.filter(t => t.userId === currentUser.id && t.status === 'pending').map(t => (
                         <div key={t.id} className="flex justify-between text-xs text-gray-400 bg-black/20 p-2 rounded"><span>{t.timestamp}</span><span>R$ {t.amount.toFixed(2)} ({t.coins.toFixed(1)} PND)</span></div>
                      ))}
                   </div>
                   <p className="text-[10px] text-gray-500 mt-2">Seus créditos serão liberados após a identificação bancária.</p>
                </div>
             )}

             <div className="bg-[#09090b] rounded-2xl border border-white/5 p-6">
                <h3 className="text-white font-bold mb-4 flex items-center gap-2"><Shield className="w-4 h-4 text-pandora-primary" /> Área Administrativa</h3>
                {isAdminSetup ? (
                   <div className="flex items-center justify-between"><p className="text-xs text-green-500 font-bold flex items-center gap-1"><Check className="w-3 h-3" /> Configuração Ativa</p><button onClick={() => setView('admin_login')} className="bg-white/5 hover:bg-white/10 text-gray-300 px-4 py-2 rounded-lg text-xs font-bold uppercase transition-colors">Acesso Painel</button></div>
                ) : (
                   <div className="flex items-center justify-between"><p className="text-xs text-gray-500">Configuração inicial pendente.</p><button onClick={() => setShowAdminSetupModal(true)} className="bg-pandora-primary/20 text-pandora-primary hover:bg-pandora-primary/30 px-4 py-2 rounded-lg text-xs font-bold uppercase transition-colors border border-pandora-primary/20">Configurar Acesso</button></div>
                )}
             </div>
          </div>
       );
    }

    if (view === 'create') {
       return (
         <div className="container mx-auto px-4 py-8">
            <CreateGigForm onSubmit={handleSaveGig} onCancel={() => setView('home')} initialDescription={draftDescription} initialType={createFormInitialType} currentUser={currentUser} onRedirectToSignup={() => setView('signup')} gigToEdit={gigToEdit} />
         </div>
       );
    }

    if (view === 'messages') {
       return (
         <div className="container mx-auto px-4 py-8">
            <div className="max-w-2xl mx-auto space-y-4">
              <h2 className="text-2xl font-bold mb-6 text-white">Mensagens</h2>
              {chats.length === 0 && (<div className="text-center py-10 text-gray-500"><MessageSquare className="w-12 h-12 mx-auto mb-2 opacity-20" /><p>Nenhuma conversa ativa.</p><p className="text-xs">Contrate um serviço para liberar o chat.</p></div>)}
              {chats.map(chat => (<div key={chat.id} onClick={() => handleOpenChat(chat)} className="bg-pandora-card p-4 rounded-2xl border border-white/5 hover:border-pandora-primary/30 cursor-pointer flex items-center gap-4 transition-all"><img src={chat.participant.avatar} alt="" className="w-12 h-12 rounded-full border border-white/10" /><div className="flex-1"><div className="flex justify-between mb-1"><h3 className="font-bold text-white">{chat.participant.name}</h3>{chat.unreadCount > 0 && <span className="bg-pandora-primary text-white text-xs px-2 py-0.5 rounded-full">{chat.unreadCount} nova(s)</span>}</div><p className="text-sm text-gray-400 truncate">{chat.lastMessage}</p></div></div>))}
            </div>
         </div>
       );
    }

    if (view === 'chat_detail' && activeSession) {
       const currentGig = requests.find(r => r.id === activeSession.gigId);
       const isChatUnlocked = currentGig && (currentGig.status === GigStatus.IN_PROGRESS || currentGig.status === GigStatus.COMPLETED);
       return (
          <div className="container mx-auto px-4 py-8 max-w-2xl">
             <ChatInterface key={activeSession.id} session={activeSession} onBack={() => setView('messages')} onSendMessage={(text, attachment) => handleSendMessage(activeSession.id, text, attachment)} isUnlocked={isChatUnlocked} />
          </div>
       );
    }

    if (view === 'profile') {
       const myRequests = requests.filter(r => r.author.id === currentUser.id);
       return (
          <div className="container mx-auto px-4 py-8 max-w-2xl">
             <div className="bg-pandora-card rounded-3xl border border-white/10 p-8 shadow-2xl mb-8 text-center relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-24 bg-gradient-to-b from-pandora-primary/20 to-transparent"></div>
                <div className="relative z-10 flex flex-col items-center">
                   <div className="w-24 h-24 rounded-full border-4 border-pandora-bg bg-gray-800 mb-4 overflow-hidden shadow-lg relative"><img src={currentUser.avatar} alt="Me" className="w-full h-full object-cover" /></div>
                   <h2 className="text-2xl font-black text-white tracking-tight flex items-center gap-2">{currentUser.name}{currentUser.isVerified && <span title="Verificado" className="flex items-center"><ShieldCheck className="w-5 h-5 text-blue-400" /></span>}</h2>
                   {currentUser.isVerified ? <div className="flex items-center gap-1 text-amber-500 text-sm font-bold mb-6"><Star className="w-4 h-4 fill-current" /> 5.0 (Iniciante)</div> : <div className="mb-6 mt-2"><button onClick={() => setView('signup')} className="bg-red-500/20 text-red-400 border border-red-500/30 px-3 py-1 rounded-full text-xs font-bold uppercase animate-pulse hover:bg-red-500/30">Não Verificado • Completar Cadastro</button></div>}
                   <div className="grid grid-cols-3 gap-4 w-full border-t border-white/10 pt-6">
                      <div className="text-center"><p className="text-xs text-gray-500 uppercase font-bold">Pedidos</p><p className="text-xl font-mono text-white">{myRequests.filter(r => r.type === 'request').length}</p></div>
                      <div className="text-center border-l border-white/10"><p className="text-xs text-gray-500 uppercase font-bold">Ofertas</p><p className="text-xl font-mono text-white">{myRequests.filter(r => r.type === 'offer').length}</p></div>
                      <div className="text-center border-l border-white/10"><p className="text-xs text-gray-500 uppercase font-bold">Saldo</p><p className="text-xl font-mono text-pandora-secondary">{userBalance}</p></div>
                   </div>
                </div>
             </div>
             <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-8">
                <button onClick={() => setShowSupportModal(true)} className="bg-pandora-secondary/10 text-pandora-secondary border border-pandora-secondary/20 font-bold py-4 px-4 rounded-xl flex items-center justify-center gap-2 hover:bg-pandora-secondary/20 transition-colors md:col-span-2 shadow-lg shadow-orange-900/10"><Headset className="w-5 h-5" /> Fale Conosco / Sugestões</button>
                <button onClick={() => setShowSafetyModal(true)} className="bg-blue-900/20 text-blue-400 border border-blue-500/20 font-bold py-4 px-4 rounded-xl flex items-center justify-center gap-2 hover:bg-blue-900/40 transition-colors shadow-lg shadow-blue-900/10"><ShieldCheck className="w-5 h-5" /> Central de Segurança</button>
                <button onClick={handleShareApp} className="bg-white text-black font-bold py-3 px-4 rounded-xl flex items-center justify-center gap-2 hover:bg-gray-200 transition-colors shadow-lg"><Share2 className="w-4 h-4" /> Compartilhar App</button>
                <button onClick={() => {navigator.clipboard.writeText(window.location.href); alert('Link copiado! Envie para seus testadores.');}} className="bg-purple-900/20 text-purple-400 border border-purple-500/20 font-bold py-3 px-4 rounded-xl flex items-center justify-center gap-2 hover:bg-purple-900/40 transition-colors"><Link className="w-4 h-4" /> Copiar Link de Teste</button>
                <button onClick={handleResetApp} className="bg-red-900/20 text-red-500 border border-red-500/20 font-bold py-3 px-4 rounded-xl flex items-center justify-center gap-2 hover:bg-red-900/40 transition-colors"><RefreshCw className="w-4 h-4" /> Resetar Testes</button>
             </div>

             <div className="mb-8 border-t border-white/5 pt-6 flex flex-col items-center gap-2 opacity-60 hover:opacity-100 transition-opacity">
               <div className="flex items-center gap-2 text-xs font-mono text-gray-500">
                  <Code2 className="w-3 h-3" />
                  <span>v1.0.0 (APK Ready)</span>
               </div>
               <p className="text-[10px] text-gray-600">Projeto Open Source</p>
             </div>

             <div className="space-y-4">
                <h3 className="text-lg font-bold text-white flex items-center gap-2"><Activity className="w-5 h-5 text-pandora-primary" /> Meus Anúncios</h3>
                {myRequests.length === 0 ? <div className="bg-white/5 rounded-xl p-8 text-center border border-white/5"><p className="text-gray-500 mb-4">Você ainda não criou nenhum pedido ou oferta.</p><button onClick={() => handleStartCreate('request')} className="text-pandora-primary font-bold hover:text-white transition-colors">Começar Agora</button></div> : myRequests.map(req => (
