      setInspirationList(prev => prev.filter(item => item.id !== id));
    }
  };

  const handleOpenChat = (session: ChatSession) => {
    if (session.gigId) {
      const gigIndex = requests.findIndex(r => r.id === session.gigId);
      if (gigIndex > -1) {
        const gig = requests[gigIndex];
        if (gig.author.id !== currentUser.id) {
           const isAlreadyCandidate = gig.candidates.some(c => c.id === currentUser.id);
           if (!isAlreadyCandidate) {
             const updatedGig = {
               ...gig,
               status: gig.status === GigStatus.OPEN ? GigStatus.NEGOTIATING : gig.status,
               candidates: [...gig.candidates, currentUser]
             };

             // Update Service
             api.gigs.update(updatedGig);

             const updatedRequests = [...requests];
             updatedRequests[gigIndex] = updatedGig;
             setRequests(updatedRequests);
             addLog(`Usuário ${currentUser.name} entrou em negociação no pedido ${gig.id}`, 'info');
           }
        }
      }
    }
    setActiveSession(session);
    setView('chat_detail');
  };

  const handleSendMessage = async (sessionId: string, text: string, attachment?: { type: 'image' | 'video', url: string }) => {
    const newMessage: Message = {
      id: Math.random().toString(36).substr(2, 9),
      senderId: currentUser.id,
      content: text,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      isMe: true,
      attachment: attachment
    };

    // Save Service
    await api.chats.sendMessage(sessionId, newMessage);

    // Update Local
    setChats(prevChats => {
      const updatedChats = prevChats.map(chat => {
        if (chat.id === sessionId) {
          return {
            ...chat,
            lastMessage: attachment ? (attachment.type === 'image' ? '📷 Imagem' : '🎥 Vídeo') : text,
            messages: [...chat.messages, newMessage]
          };
        }
        return chat;
      });
      const updatedActive = updatedChats.find(c => c.id === sessionId);
      if (updatedActive) {
        setActiveSession(updatedActive);
      }
      return updatedChats;
    });
  };

  const handleGigClick = (request: GigRequest) => {
    setSelectedGigDetail(request);
  };

  const handleHireClick = (gigId: string) => {
    if (!currentUser.isVerified) {
        if (confirm("VOCÊ ESTÁ QUASE LÁ!\n\nPara negociar, aceitar propostas ou contratar, é necessário validar seu perfil no C.Pandox.\n\nDeseja finalizar seu cadastro agora para liberar o acesso?")) {
            setSelectedGigDetail(null); 
            setView('signup');
        }
        return;
    }
    const gig = requests.find(r => r.id === gigId);
    if (gig) {
      if (gig.author.id === currentUser.id) {
          // Owner cannot "hire" from card, they use View Candidates
          return;
      }

      // Check if chat already exists
      const existingChat = chats.find(c => c.gigId === gig.id && c.participant.id === gig.author.id);
      if (existingChat) {
          handleOpenChat(existingChat);
          return;
      }

      // Create new chat negotiation
      const newChatSession: ChatSession = {
          id: `chat_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
          gigId: gig.id,
          participant: gig.author,
          lastMessage: "Iniciou interesse no pedido.",
          unreadCount: 0,
          messages: []
      };

      handleOpenChat(newChatSession);
      // Logic inside handleOpenChat adds user to candidates
    }
  };

