  const handleViewCandidates = (gig: GigRequest) => {
     setSelectedGigForCandidates(gig);
     setShowCandidatesModal(true);
  };

  // OWNER: Select a candidate to start chat specifically with them
  const handleSelectCandidate = async (candidate: UserType) => {
      if (!selectedGigForCandidates) return;

      // Check if chat already exists for this candidate on this gig
      const existingChat = chats.find(c => c.gigId === selectedGigForCandidates.id && c.participant.id === candidate.id);

      if (existingChat) {
          setShowCandidatesModal(false);
          setActiveSession(existingChat);
          setView('chat_detail');
          return;
      }

      // Create new chat
      const newChatId = `chat_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`;
      const newChatSession: ChatSession = {
          id: newChatId,
          gigId: selectedGigForCandidates.id,
          participant: candidate,
          lastMessage: "Olá! Vi seu interesse no meu pedido. Vamos conversar?",
          unreadCount: 0,
          messages: [
              {
                  id: 'init_owner',
                  senderId: currentUser.id,
                  content: "Olá! Vi seu interesse no meu pedido. Vamos conversar?",
                  timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                  isMe: true
              }
          ]
      };

      await api.chats.create(newChatSession);
      setChats(prev => [newChatSession, ...prev]);

      setShowCandidatesModal(false);
      setActiveSession(newChatSession);
      setView('chat_detail');
  };


  const confirmHire = async () => {
    if (!selectedGigForHire) return;
    if (!paymentPixKey) {
      alert("Por favor, insira sua chave Pix para validar a transação.");
      return;
    }
    if (userBalance >= selectedGigForHire.budget) {
      setIsProcessingPayment(true);
      setTimeout(async () => {
        setUserBalance(prev => prev - selectedGigForHire.budget);
        addLog(`Cofre ativado para pedido ${selectedGigForHire.id}. Valor: ${selectedGigForHire.budget}`, 'info');

        const updatedGig = { ...selectedGigForHire, status: GigStatus.IN_PROGRESS };
        await api.gigs.update(updatedGig);

        const updatedRequests = requests.map(req => 
          req.id === selectedGigForHire.id 
            ? updatedGig
            : req
        );
        setRequests(updatedRequests);

        const newChatId = `chat_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`;

        if (activeSession && activeSession.gigId === selectedGigForHire.id) {
            const systemMsg: Message = {
               id: 'sys_safe',
               senderId: 'system',
               content: `Cofre Pandox ativado! O valor de ${selectedGigForHire.budget} PND está seguro.`,
               timestamp: new Date().toLocaleTimeString(),
               isMe: false
            };
            await api.chats.sendMessage(activeSession.id, systemMsg);
        }

        setShowPaymentModal(false);
        setSelectedGigForHire(null);
        setPaymentPixKey('');
        setIsProcessingPayment(false);
        alert("Pagamento confirmado e valor retido no Cofre! O chat foi liberado.");
      }, 2500);
    } else {
      alert("Saldo insuficiente. Recarregue suas Pandox Coins.");
      setIsProcessingPayment(false);
    }
  };

  const handleReleaseFunds = async (gigId: string) => {
    const gig = requests.find(r => r.id === gigId);
    if (!gig) return;
    const commissionFee = Math.floor(gig.budget * (commissionRate / 100));
    const providerAmount = gig.budget - commissionFee;
    setAppRevenue(prev => prev + commissionFee);
    addLog(`Pagamento liberado (ID: ${gigId}). Comissão App: ${commissionFee} PND`, 'success');

    const updatedGig = { ...gig, status: GigStatus.COMPLETED };
    await api.gigs.update(updatedGig);

    const updatedRequests = requests.map(req => 
      req.id === gigId 
        ? updatedGig 
        : req
    );
    setRequests(updatedRequests);
    alert(`
      Serviço confirmado e concluído!
      --------------------------------
      Valor Total: ${gig.budget} PND
      Taxa da Plataforma (${commissionRate}%): -${commissionFee} PND (Depositado em c.pandox)
      Valor Líquido Liberado ao Prestador: ${providerAmount} PND
    `);
  };

  const handleGeneratePix = () => {
    if (!depositAmount || Number(depositAmount) <= 0) return;

    // Add random cents for identification
    const cents = Math.floor(Math.random() * 99) + 1;
    const exactAmount = Number(depositAmount) + (cents / 100);
    setIdentifiedDepositAmount(exactAmount);

    const mockPayload = `00020126580014br.gov.bcb.pix0136${Math.random().toString(36).substring(7)}520400005303986540${exactAmount.toFixed(2).replace('.', '')}5802BR5913C PANDOX LTDA6008BRASILIA62070503***6304${Math.floor(Math.random() * 9000) + 1000}`;
    setGeneratedPixCode(mockPayload);
    setTopUpStep('payment');
  };

  const handleConfirmPixPayment = () => {
    setTopUpStep('processing');
    setTimeout(async () => {
      // Credit the identified amount
      const amountToAdd = identifiedDepositAmount / 10; 
      const newTrans: Transaction = {
         id: Math.random().toString(36).substr(2, 9),
         userId: currentUser.id,
         userName: currentUser.name,
         amount: identifiedDepositAmount,
         coins: amountToAdd,
         type: 'deposit',
         status: 'pending',
         pixCode: generatedPixCode,
         timestamp: new Date().toLocaleString()
      };

      await api.system.addTransaction(newTrans);

      setTransactions([newTrans, ...transactions]);
      addLog(`Novo depósito pendente de R$ ${identifiedDepositAmount.toFixed(2)} por ${currentUser.name}`, 'info');
      setTopUpStep('amount');
      setDepositAmount('');
      setIdentifiedDepositAmount(0);
      setShowTopUpModal(false);
      alert(`Depósito registrado! Seu saldo será atualizado assim que o pagamento for identificado pelo sistema bancário.`);
    }, 2000);
  };

  const handleAdminApproveTransaction = (transId: string) => {
     const trans = transactions.find(t => t.id === transId);
     if (!trans) return;
     setAllUsers(users => users.map(u => {
        if (u.id === trans.userId) {
           return { ...u, walletBalance: u.walletBalance + trans.coins };
        }
        return u;
     }));
     if (trans.userId === currentUser.id) {
        setUserBalance(prev => prev + trans.coins);
     }
     setTransactions(transactions.map(t => t.id === transId ? { ...t, status: 'approved' } : t));
     setAppRevenue(prev => prev + trans.coins);
     addLog(`Depósito de R$ ${trans.amount} aprovado para ${trans.userName}`, 'success');
  };

  const handleAdminRejectTransaction = (transId: string) => {
     if(confirm('Rejeitar este pagamento?')) {
        setTransactions(transactions.map(t => t.id === transId ? { ...t, status: 'rejected' } : t));
        addLog(`Depósito rejeitado (ID: ${transId})`, 'warning');
     }
  };

