  // ATUALIZADO PARA COPIAR O LINK DO APLICATIVO
  const handleShareApp = () => {
    const url = window.location.href;
    navigator.clipboard.writeText(url).then(() => {
      alert("Link do aplicativo copiado com sucesso! Agora você pode compartilhá-lo onde desejar.");
    }).catch(err => {
      console.error('Erro ao copiar link:', err);
      // Fallback para abertura de compartilhamento se disponível
      if (navigator.share) {
        navigator.share({ title: 'c.pandox', url: url });
      }
    });
  };

  const runTransferSequence = () => {
    let currentStep = 0;
    setTransferConsoleLogs([]);
    const interval = setInterval(() => {
      if (currentStep >= 7) {
        clearInterval(interval);
        addLog(`Saque Corporativo Realizado. Valor: R$ ${(appRevenue * 10).toFixed(2)}`, 'warning');
        setAppRevenue(0);
        setShowAdminWithdrawModal(false);
        setAdminWithdrawPass('');
        setAdminStep('auth');
        alert('Autenticação Confirmada. Valor transferido com sucesso.');
      } else {
        const steps = [
            "Iniciando...", "Conectando...", "Validando...", "Autenticando...", "Debitando...", "Confirmando...", "SUCESSO"
        ];
        setTransferConsoleLogs(prev => [...prev, steps[currentStep] || "..."]);
        currentStep++;
      }
    }, 800);
