const SignupForm: React.FC<SignupFormProps> = ({ onSignup, onCancel, adminPixKey }) => {
  const [step, setStep] = useState<1 | 2>(1);
  const [role, setRole] = useState<'requester' | 'worker' | 'both'>('requester');
  const [selectedAvatar, setSelectedAvatar] = useState(AVAILABLE_AVATARS[0].url);

  const [formData, setFormData] = useState({
    name: '',
    cpf: '',
    phone: '',
    pixKey: ''
  });

  const [addressData, setAddressData] = useState({
    cep: '',
    street: '',
    number: '',
    neighborhood: '',
    city: ''
  });

  const [isVerifyingIdentity, setIsVerifyingIdentity] = useState(false);
  const [verificationStatus, setVerificationStatus] = useState<'idle' | 'success' | 'error'>('idle');
  const [verificationMessage, setVerificationMessage] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [pixPayload, setPixPayload] = useState('');

  // --- CAMPANHA DE LANÇAMENTO ---
  // Grátis para Requester/Worker (Primeiros 1000). 
  // Plano 'Ambos' custa R$ 2,00.
  const [randomCents] = useState(() => Math.floor(Math.random() * 90) + 10); 
  const baseFee = role === 'both' ? 2 : 0;
  const fee = baseFee > 0 ? baseFee + (randomCents / 100) : 0;

  useEffect(() => {
     if (step === 2 && fee > 0) {
        const mock = `00020126580014br.gov.bcb.pix0136${Math.random().toString(36).substring(7)}520400005303986540${fee.toFixed(2).replace('.', '')}5802BR5913C PANDOX LTDA6008BRASILIA62070503***6304${Math.floor(Math.random() * 9000) + 1000}`;
        setPixPayload(mock);
     }
  }, [step, fee, role]);

  const isValidCPF = (cpf: string) => {
    cpf = cpf.replace(/[^\d]+/g, '');
    if (cpf.length !== 11 || /^(\d)\1+$/.test(cpf)) return false;
    let sum = 0;
    let remainder;
    for (let i = 1; i <= 9; i++) sum += parseInt(cpf.substring(i - 1, i)) * (11 - i);
    remainder = (sum * 10) % 11;
    if ((remainder === 10) || (remainder === 11)) remainder = 0;
    if (remainder !== parseInt(cpf.substring(9, 10))) return false;
    sum = 0;
    for (let i = 1; i <= 10; i++) sum += parseInt(cpf.substring(i - 1, i)) * (12 - i);
    remainder = (sum * 10) % 11;
    if ((remainder === 10) || (remainder === 11)) remainder = 0;
    if (remainder !== parseInt(cpf.substring(10, 11))) return false;
    return true;
  };

  const handleNext = async () => {
    if (!formData.name || !formData.cpf || !formData.phone || !formData.pixKey) {
      alert("Por favor, preencha todos os dados pessoais obrigatórios.");
      return;
    }
    if (!addressData.cep || !addressData.street || !addressData.number || !addressData.neighborhood || !addressData.city) {
      alert("Por favor, preencha o endereço completo.");
      return;
    }

    setVerificationStatus('idle');
    setVerificationMessage('');
    setIsVerifyingIdentity(true);

    if (!isValidCPF(formData.cpf)) {
        setIsVerifyingIdentity(false);
        setVerificationStatus('error');
        setVerificationMessage('CPF Inválido. Verifique os dígitos e tente novamente.');
        return;
    }

    try {
        const [nameCheck] = await Promise.all([
            validateRegistrationName(formData.name),
            new Promise(resolve => setTimeout(resolve, 2000))
        ]);

        if (!nameCheck.valid) {
            setIsVerifyingIdentity(false);
            setVerificationStatus('error');
            setVerificationMessage(`Nome Rejeitado: ${nameCheck.message || 'Informe seu nome civil completo.'}`);
            return;
        }

        setIsVerifyingIdentity(false);
        setVerificationStatus('success');
        setTimeout(() => setStep(2), 800);

    } catch (e) {
        setIsVerifyingIdentity(false);
        setStep(2);
    }
  };

  const handleFinish = () => {
    setIsProcessing(true);
    setTimeout(() => {
      const fullAddressString = `${addressData.street}, ${addressData.number} - ${addressData.neighborhood}, ${addressData.city} - CEP: ${addressData.cep}`;
      const newUser: UserType = {
        id: `user_${Math.random().toString(36).substr(2, 9)}`,
        name: formData.name,
        avatar: selectedAvatar,
        rating: 5.0,
        walletBalance: 0,
        status: 'active',
        cpf: formData.cpf,
        address: fullAddressString,
        phone: formData.phone,
        pixKey: formData.pixKey,
        role: role,
        isVerified: true
      };
      onSignup(newUser);
      setIsProcessing(false);
    }, 2000);
  };

  const copyPix = (text: string) => {
    navigator.clipboard.writeText(text);
    alert("Código Pix copiado!");
  };

  const formatCPF = (value: string) => {
    return value
      .replace(/\D/g, '')
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d{1,2})/, '$1-$2')
      .slice(0, 14);
  };

  const formatCEP = (value: string) => {
    return value.replace(/\D/g, '').replace(/^(\d{5})(\d)/, '$1-$2').slice(0, 9);
  };

  return (
    <div className="max-w-xl mx-auto py-8 px-4">
      <div className="bg-pandora-card border border-white/10 rounded-3xl p-8 shadow-2xl relative overflow-hidden">
        {/* Progress Bar */}
        <div className="absolute top-0 left-0 w-full h-1 bg-gray-800">
          <div 
            className="h-full bg-pandora-primary transition-all duration-500" 
            style={{ width: step === 1 ? '50%' : '100%' }}
          ></div>
        </div>

        <div className="mb-6 text-center">
          <h2 className="text-2xl font-black text-white uppercase tracking-tight mb-2">
            Inscrição C.Pandox
          </h2>
          <p className="text-sm text-gray-400">
            {step === 1 ? 'Perfil e Identidade' : 'Ativação de Conta'}
          </p>
        </div>

        <div className="bg-gradient-to-r from-purple-600/20 to-orange-600/20 p-3 rounded-xl mb-6 text-center border border-white/10">
           <p className="text-white font-bold text-xs uppercase tracking-widest flex items-center justify-center gap-2">
              <PartyPopper className="w-4 h-4 text-amber-400" /> Campanha: Primeiros 1000 Grátis!
           </p>
        </div>

        {isVerifyingIdentity && (
            <div className="absolute inset-0 z-50 bg-pandora-card/95 backdrop-blur-sm flex flex-col items-center justify-center p-8 text-center animate-in fade-in duration-300">
                <Scale className="w-16 h-16 text-blue-400 mb-4 animate-bounce" />
                <h3 className="text-xl font-bold text-white mb-2">Validando Identidade...</h3>
                <p className="text-sm text-gray-400">Consultando bases oficiais para garantir sua segurança.</p>
            </div>
        )}

        {step === 1 && (
          <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">

            {/* AVATAR SELECTOR */}
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase mb-3 ml-1">Escolha sua Aparência *</label>
              <div className="flex overflow-x-auto pb-4 gap-3 custom-scrollbar snap-x">
                 {AVAILABLE_AVATARS.map((avatar) => (
                    <button
                       key={avatar.id}
                       onClick={() => setSelectedAvatar(avatar.url)}
                       className={`relative shrink-0 w-16 h-16 rounded-full border-2 transition-all snap-start ${
                          selectedAvatar === avatar.url 
                          ? 'border-pandora-primary ring-4 ring-pandora-primary/20 scale-110' 
                          : 'border-white/10 grayscale hover:grayscale-0 hover:border-white/30'
                       }`}
                    >
                       <img src={avatar.url} className="w-full h-full rounded-full" alt="Avatar" />
                       {selectedAvatar === avatar.url && (
                          <div className="absolute -top-1 -right-1 bg-pandora-primary text-white rounded-full p-0.5 shadow-lg">
                             <Check className="w-3 h-3" />
                          </div>
                       )}
                    </button>
                 ))}
              </div>
            </div>

            {/* Role Selection */}
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase mb-3 ml-1">Modalidade de Uso</label>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
                <button
                  onClick={() => setRole('requester')}
                  className={`p-3 rounded-xl border transition-all ${role === 'requester' ? 'bg-pandora-primary/20 border-pandora-primary text-white' : 'bg-black/20 border-white/10 text-gray-500'}`}
                >
                  <p className="font-bold text-[10px]">CONTRATANTE</p>
                  <p className="text-[10px] text-green-400 font-bold">GRÁTIS</p>
                </button>
                <button
                  onClick={() => setRole('worker')}
                  className={`p-3 rounded-xl border transition-all ${role === 'worker' ? 'bg-pandora-secondary/20 border-pandora-secondary text-white' : 'bg-black/20 border-white/10 text-gray-500'}`}
                >
                  <p className="font-bold text-[10px]">PRESTADOR</p>
                  <p className="text-[10px] text-green-400 font-bold">GRÁTIS</p>
                </button>
                <button
                  onClick={() => setRole('both')}
                  className={`p-3 rounded-xl border transition-all ${role === 'both' ? 'bg-purple-600/20 border-purple-500 text-white' : 'bg-black/20 border-white/10 text-gray-500'}`}
                >
                  <p className="font-bold text-[10px]">AMBOS</p>
                  <p className="text-[10px] text-amber-500 font-bold">R$ 2,00</p>
                </button>
              </div>
              <p className="text-[9px] text-gray-500 mt-2 text-center">* Promoção limitada aos primeiros 1000 usuários em fase beta.</p>
            </div>

            {/* Form Inputs */}
            <div className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-gray-400 mb-1 ml-1">Nome Civil Completo *</label>
                <input 
                  type="text" 
                  value={formData.name}
                  onChange={(e) => setFormData({...formData, name: e.target.value})}
                  className="w-full bg-black/40 border border-white/10 rounded-xl p-3 text-white outline-none focus:border-pandora-primary"
                  placeholder="Seu nome conforme documento"
                />
              </div>

              <div className="flex gap-4">
                <div className="flex-1">
                  <label className="block text-xs font-bold text-gray-400 mb-1 ml-1">CPF *</label>
                  <input 
                    type="text" 
                    value={formData.cpf}
                    onChange={(e) => setFormData({...formData, cpf: formatCPF(e.target.value)})}
                    className="w-full bg-black/40 border border-white/10 rounded-xl p-3 text-white outline-none focus:border-pandora-primary"
                    placeholder="000.000.000-00"
                  />
                </div>
                <div className="flex-1">
                  <label className="block text-xs font-bold text-gray-400 mb-1 ml-1">Celular *</label>
                  <input 
                    type="tel" 
                    value={formData.phone}
                    onChange={(e) => setFormData({...formData, phone: e.target.value})}
                    className="w-full bg-black/40 border border-white/10 rounded-xl p-3 text-white outline-none focus:border-pandora-primary"
                    placeholder="(00) 00000-0000"
                  />
                </div>
              </div>

              <div className="bg-white/5 p-4 rounded-xl border border-white/5 space-y-3">
                 <p className="text-[10px] font-bold text-gray-500 uppercase flex items-center gap-2"><MapPin className="w-3 h-3"/> Endereço de Residência</p>
