                         <span className="text-xl font-mono font-bold text-white">R$ {fee.toFixed(2).replace('.', ',')}</span>
                      </div>
                      <p className="text-[10px] text-gray-400 leading-relaxed">
                         <AlertTriangle className="w-3 h-3 inline mr-1 text-amber-500" /> 
